#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { fileURLToPath } from "node:url";

const PAYLOAD = {"src/lib/musicPlayer.ts":"","src/lib/audio/mvpStudioEngine.ts":"","src/lib/audio/mvpStudioDsp.worklet.js":"","src/features/music/MusicMiniPlayer.tsx":"","dsp/studio/mvp_studio_dsp.cpp":"","public/audio/mvpStudioEngine.wasm":"","scripts/build-mvp-studio-wasm.sh":"","scripts/test-mvp-studio-v5-advanced.mjs":""};
const EXPECTED = {"src/lib/musicPlayer.ts":"268a738368a9a1001bea80e641ce9b79096c8a80b1fe906f67be34b0b31f4723","src/lib/audio/mvpStudioEngine.ts":"3ec8576148c713c93b7484c90f45095cf182cbc9e1e755dcf75e5cfbb6d70338","src/lib/audio/mvpStudioDsp.worklet.js":"7b009dd7820bb3c0babcd9be2d19eaa52603a53c4c00217598b42826d4f0b854","src/features/music/MusicMiniPlayer.tsx":"27b9c8072a2e6a10ae5e01b5832ea00fea9a8ee9d73bd6507b350ac750319940","dsp/studio/mvp_studio_dsp.cpp":"44c16070e74318d400a4b060e85d6a2207f2213c0b6285fb83d3f1b23aed01d0","public/audio/mvpStudioEngine.wasm":"af9c531590cf1f3872fe9ef2ffa28b7c4c1877d106f1569b253611b1867be2be","scripts/build-mvp-studio-wasm.sh":"25a6e3711d21c23b9f7f3a8767978a00ac61b20fb548c6d3a292355f5b3a11ae","scripts/test-mvp-studio-v5-advanced.mjs":"d86a66c01fcef5c2b3db52d38fee98a21f16953a747e934ac8fbe84c58867c04"};
const here = path.dirname(fileURLToPath(import.meta.url));
function isRepo(dir) { return fs.existsSync(path.join(dir,"package.json")) && fs.existsSync(path.join(dir,"src")); }
let root = process.cwd();
if (!isRepo(root)) {
  if (isRepo(path.resolve(here,".."))) root=path.resolve(here,"..");
  else if (isRepo(here)) root=here;
  else if (isRepo(path.resolve(process.cwd(),".."))) root=path.resolve(process.cwd(),"..");
  else { console.error("Could not locate MVPTrainerPro-Personal repo root. Put this installer in the repo scripts folder, or run it from the repo root."); process.exit(1); }
}
const stamp = new Date().toISOString().replace(/[:.]/g,"-");
const backupRoot = path.join(root,".mvp-backups",`r10-advanced-audio-${stamp}`);
let changed=0, unchanged=0;
const sha = b => crypto.createHash("sha256").update(b).digest("hex");
for (const [rel,b64] of Object.entries(PAYLOAD)) {
  const target=path.join(root,...rel.split("/"));
  const data=Buffer.from(b64,"base64");
  if (sha(data)!==EXPECTED[rel]) throw new Error(`Embedded checksum failed: ${rel}`);
  if (fs.existsSync(target)) {
    const existing=fs.readFileSync(target);
    if (sha(existing)===EXPECTED[rel]) { unchanged++; continue; }
    const backup=path.join(backupRoot,...rel.split("/"));
    fs.mkdirSync(path.dirname(backup),{recursive:true}); fs.copyFileSync(target,backup);
  }
  fs.mkdirSync(path.dirname(target),{recursive:true}); fs.writeFileSync(target,data);
  if (rel.endsWith('.sh')) { try { fs.chmodSync(target,0o755); } catch {} }
  if (sha(fs.readFileSync(target))!==EXPECTED[rel]) throw new Error(`Write verification failed: ${rel}`);
  changed++;
}
console.log(`MVP Trainer Pro R10 Advanced Audio Engine installed.`);
console.log(`Repo: ${root}`);
console.log(`Updated: ${changed}  Already current: ${unchanged}`);
if (fs.existsSync(backupRoot)) console.log(`Backups: ${backupRoot}`);
console.log(`Next: cd /d "${root}"`);
console.log(`Then: npm run build`);
